"""Column profiling: empty-cell counts and numeric detection."""

from __future__ import annotations


def is_number(text: str) -> bool:
    """True when the text parses as a float."""
    try:
        float(text)
    except ValueError:
        return False
    return True


def profile_columns(header: list[str], rows: list[list[str]]) -> dict[str, dict]:
    """For each column: how many cells are empty and whether the rest are numeric."""
    report = {}
    for index, name in enumerate(header):
        cells = [row[index].strip() if index < len(row) else "" for row in rows]
        filled = [cell for cell in cells if cell]
        report[name] = {
            "empty": len(cells) - len(filled),
            "numeric": bool(filled) and all(is_number(cell) for cell in filled),
        }
    return report

