"""Row cleaning: trim cells, drop blank rows, and remove duplicates."""

from __future__ import annotations

from csvclean.convert import convert_cell


def clean_cell(value: str) -> str:
    """Trim whitespace and collapse internal runs of spaces."""
    return " ".join(value.split())


def is_blank(row: list[str]) -> bool:
    """True when every cell in the row is empty after trimming."""
    return all(not clean_cell(cell) for cell in row)


def dedupe(rows: list[list[str]]) -> list[list[str]]:
    """Drop repeated rows, keeping the first occurrence."""
    seen: set[tuple[str, ...]] = set()
    unique = []
    for row in rows:
        key = tuple(row)
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique


def clean_rows(rows: list[list[str]], convert: bool = False) -> list[list]:
    """Trim cells, drop blank and duplicate rows, optionally convert numbers."""
    cleaned = dedupe([[clean_cell(cell) for cell in row] for row in rows if not is_blank(row)])
    return [[convert_cell(cell) for cell in row] for row in cleaned] if convert else cleaned

